sys_script_include.script:
var BedService = Class.create();

BedService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Bed record exists.
     *
     * @param {String} bedSysId
     * @return {Boolean}
     */
    bedExists: function(bedSysId) {

        if (this.validationUtils.isEmpty(bedSysId)) {
            return false;
        }

        var bed = new GlideRecord(
            'x_2130921_caresy_0_bed'
        );

        if (!bed.isValid()) {
            gs.error(
                'BedService: Bed table is invalid.'
            );
            return false;
        }

        return bed.get(bedSysId);
    },

    /**
     * Retrieve a Bed record.
     *
     * @param {String} bedSysId
     * @return {GlideRecord|null}
     */
    getBed: function(bedSysId) {

        if (this.validationUtils.isEmpty(bedSysId)) {
            return null;
        }

        var bed = new GlideRecord(
            'x_2130921_caresy_0_bed'
        );

        if (!bed.isValid()) {
            gs.error(
                'BedService: Bed table is invalid.'
            );
            return null;
        }

        if (bed.get(bedSysId)) {
            return bed;
        }

        return null;
    },

    /**
     * Check whether a Bed is currently available.
     *
     * @param {String} bedSysId
     * @return {Boolean}
     */
    isBedAvailable: function(bedSysId) {

        var bed = this.getBed(bedSysId);

        if (!bed) {
            return false;
        }

        return bed.getValue('bed_status') == 'Available';
    },

    type: 'BedService'
};
